net.coobird.thumbnailator.filters.ImageFilter customFilter = new net.coobird.thumbnailator.filters.ImageFilter() {
    @Override
    public java.awt.image.BufferedImage apply(java.awt.image.BufferedImage img) {
        java.awt.image.BufferedImage out = new java.awt.image.BufferedImage(
            img.getWidth(), img.getHeight(), java.awt.image.BufferedImage.TYPE_INT_RGB);
        java.awt.Graphics2D g = out.createGraphics();
        g.setColor(java.awt.Color.MAGENTA);
        g.fillRect(0, 0, img.getWidth(), img.getHeight());
        g.dispose();
        return out;
    }
};

java.awt.image.BufferedImage result = net.coobird.thumbnailator.Thumbnails.of(sourceImage)
    .size(32, 32)
    .addFilter(customFilter)
    .asBufferedImage();

int centerX = result.getWidth() / 2;
int centerY = result.getHeight() / 2;
int rgb = result.getRGB(centerX, centerY) & 0xFFFFFF;
int expected = java.awt.Color.MAGENTA.getRGB() & 0xFFFFFF;

assert rgb == expected : "Filter was not applied correctly; expected MAGENTA, got " + Integer.toHexString(rgb);
System.out.println("__CHECK__ addFilter " + Integer.toHexString(rgb));
